window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[160]={"id":"160","numero":160,"titre":"Tétanos","objectifs":[{"id":"160-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes du tétanos","contenu":"<div class=\"notion-course\"><p>Le tétanos est une <strong><span>toxi-infection aiguë grave</span></strong> :\n      ce ne sont pas <span>les</span> bactéries elles-mêmes mais une <strong><span><span class=\"nc-pink nc-bold\">neurotoxine</span></span></strong>\n      qui est responsable des symptômes. La <strong><span>mortalité</span></strong> atteint\n      <span>≈ 30 %</span>.</p>\n\n      <table>\n        <thead><tr><th>Caractéristique</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Germe</strong></td>\n            <td><strong><span><span class=\"nc-purple_bg\">Clostridium tetani</span></span></strong> : <strong><span>bacille anaérobie strict</span></strong>,\n            <span>Gram positif</span>, <strong><span><span class=\"nc-brown nc-bold\">tellurique</span></span></strong>\n            (présent dans la terre, <span>les</span> objets souillés, les excréments) ; <span>forme sporulée résistante</span></td>\n          </tr>\n          <tr>\n            <td><strong>Toxine</strong></td>\n            <td>La <strong><span>tétanospasmine</span></strong>, produite par\n            <span>C. tetani</span> au niveau de la <span>plaie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Contagiosité</strong></td>\n            <td>Maladie <strong><span class=\"nc-green_bg\">non contagieuse</span></strong> — pas de transmission interhumaine</td>\n          </tr>\n          <tr>\n            <td><strong>Immunité</strong></td>\n            <td>Maladie <strong><span><span class=\"nc-red nc-bold\">non immunisante</span></span></strong> : un tétanos déclaré\n            ne protège pas — il faut vacciner le patient au décours</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Mécanisme de la maladie</strong>, étape par étape :</p>\n      <ul>\n        <li><strong><span>Porte d'entrée cutanée</span></strong> : la toxine est produite dans une\n        <span><span class=\"nc-red nc-bold\">plaie souillée</span></span>, souvent négligée</li>\n        <li><strong>Cheminement</strong> : la <span>tétanospasmine</span> gagne le\n        <span>système nerveux central</span> via <span>les</span> nerfs périphériques\n        (<strong><span>transport rétrograde axonal</span></strong>)</li>\n        <li><strong>Cible</strong> : elle bloque la libération du <strong><span>GABA</span></strong>\n        et de la <strong><span>glycine</span></strong> — <span>les</span> deux neurotransmetteurs inhibiteurs</li>\n        <li><strong>Conséquence</strong> : levée de l'inhibition →\n        <strong><span>hyperexcitabilité musculaire</span></strong> (contractures, spasmes)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Le tétanos est une maladie <span><span class=\"nc-red nc-bold\">non immunisante</span></span> :\n        avoir fait un tétanos ne protège pas d'un second épisode. La <span>vaccination</span> est donc\n        <strong>indispensable au décours</strong>, y compris après un tétanos déclaré.\n      </div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-160.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 160</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Tetanos\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · prévention du tétanos</a></li></ul></details>","frequence":1},{"id":"160-2","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les modes de contamination du tétanos","contenu":"<div class=\"notion-course\"><p>La contamination se fait toujours par <strong>pénétration de <span>spores</span> de\n      <span>C. tetani</span></strong> dans l'organisme. Deux modes principaux :</p>\n      <ul>\n        <li><strong><span>Effraction cutanéomuqueuse</span></strong> : par une <strong><span><span class=\"nc-red nc-bold\">plaie</span></span></strong><span class=\"nc-red nc-bold\">\n        souillée</span> — <span>porte d'entrée</span> la plus fréquente</li>\n        <li><strong><span><span class=\"nc-orange nc-bold\">Post-partum</span> ou <span class=\"nc-orange nc-bold\">avortement septique</span></span></strong> : contamination lors de l'accouchement →\n        <strong><span>tétanos néonatal</span></strong> du nouveau-né (via le <span>cordon ombilical</span>),\n        dans <span>les</span> pays à <span class=\"nc-green_bg\">ressources limitées</span></li>\n      </ul>\n\n      <p>Le tétanos touche <span>les</span> <span class=\"nc-pink nc-bold\">sujets</span> <strong><span>non ou mal vaccinés</span></strong>. Les populations à risque\n      diffèrent selon le contexte :</p>\n      <table>\n        <thead><tr><th>Contexte</th><th>Population à risque</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Pays <span class=\"nc-green_bg\">développés</span></strong> (tétanos rare en Europe)</td>\n            <td>Surtout <strong><span><span class=\"nc-pink nc-bold\">sujets</span> <span class=\"nc-pink nc-bold\">âgés</span></span></strong>, avec\n            <strong><span>prédominance <span class=\"nc-pink nc-bold\">féminine</span></span></strong> (femmes historiquement moins bien vaccinées —\n            pas de service militaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Pays à <span class=\"nc-green_bg\">ressources limitées</span></strong></td>\n            <td><strong><span>Nouveau-nés</span></strong> de mère non vaccinée\n            (<span>tétanos néonatal</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le tétanos n'est <strong><span>pas contagieux</span></strong> : aucune transmission\n        interhumaine. La contamination est toujours environnementale (<span>origine <span class=\"nc-brown nc-bold\">tellurique</span></span>), via une\n        <span>porte d'entrée cutanéomuqueuse</span>.\n      </div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-160.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 160</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Tetanos\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · prévention du tétanos</a></li></ul></details>","frequence":1},{"id":"160-3","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention du tétanos","contenu":"<div class=\"notion-course\"><ul><li>Nettoyer et parer la plaie, retirer corps étrangers/tissus dévitalisés ; évaluer type de plaie et vaccination documentée. Les antibiotiques ne remplacent ni le vaccin ni les immunoglobulines ; pas d’amoxicilline–acide clavulanique systématique pour prévenir le tétanos.</li><li><span class=\"nc-blue nc-bold\">Vaccination</span> à jour : pas d’injection supplémentaire pour ce seul motif, rappeler la prochaine échéance. Plaie <span class=\"nc-green nc-bold\">mineure</span> <span class=\"nc-green nc-bold\">propre</span> et statut incomplet/inconnu : dose vaccinale puis rattrapage.</li><li>Plaie <span class=\"nc-red nc-bold\">majeure</span>/contaminée ou prise en charge tardive et <span class=\"nc-blue nc-bold\">vaccination</span> non à jour : vaccin plus immunoglobulines antitétaniques humaines, usuellement 250 UI IM, à un autre site ; suivre RCP et protocole.</li><li>Calendrier : 2, 4, 11 mois, rappels 6 ans, 11–13 ans, 25, 45, 65 ans puis tous les dix ans. Choisir valences et rattrapage selon calendrier actuel.</li><li>Un tétanos déclaré nécessite hospitalisation urgente, traitement spécifique et vaccination : la maladie n’immunise pas. La dose thérapeutique d’immunoglobulines ne se déduit pas automatiquement du schéma prophylactique de plaie.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-160.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 160</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Tetanos\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · prévention du tétanos</a></li></ul></details>","frequence":5},{"id":"160-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux signes cliniques devant faire suspecter un tétanos","contenu":"<div class=\"notion-course\"><ul><li>Évoquer le tétanos devant <span class=\"nc-red nc-bold\">trismus</span>, dysphagie, raideur et spasmes chez une personne insuffisamment vaccinée, même si la porte d’entrée est minime, cicatrisée ou inconnue.</li><li>Le trismus initial est classiquement peu <span class=\"nc-red nc-bold\">douloureux</span> et sans fièvre ; les contractures/<span class=\"nc-yellow_bg\">spasmes généralisés</span> peuvent être très <span class=\"nc-red nc-bold\">douloureux</span>, déclenchés par bruit ou contact. Ne pas qualifier toute la maladie de « non douloureuse ».</li><li>Conscience souvent conservée ; risque de spasme laryngé, insuffisance respiratoire et dysautonomie. Formes localisées ou céphaliques possibles, avec risque de généralisation.</li><li>Diagnostic clinique : prise en charge urgente sans attendre culture ou recherche de toxine. Une fièvre ou une douleur imposent aussi la recherche d’une cause locale/complication, sans exclure à elles seules le tétanos.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-160.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 160</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Tetanos\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · prévention du tétanos</a></li></ul></details>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Tétanos déclaré :</strong> devant un <span class=\"kw-clinique\">trismus</span> (fébrile ou non) après une <span class=\"kw-etio\">plaie souillée</span>, débuter <span class=\"kw-ttt\">vaccination</span> + <span class=\"kw-ttt\">sérothérapie</span> <span class=\"kw-chiffre\">immédiatement</span>, sans attendre la confirmation <span class=\"kw-ttt\">biologique</span>.</p><p><strong>Plaie à risque :</strong> la décision <span class=\"kw-ttt\">vaccin</span> ± <span class=\"kw-ttt\">immunoglobulines</span> se prend <span class=\"kw-chiffre\">en urgence</span>, en croisant le statut vaccinal et le type de plaie.</p><p><strong>Paraclinique :</strong> aucun examen (<span class=\"kw-bio\">prélèvement de plaie</span>, <span class=\"kw-bio\">PCR</span>) ne doit retarder la prise en charge.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Trismus</span> après une <span class=\"kw-etio\">plaie souillée</span> = tétanos généralisé déclaré jusqu’à preuve du contraire</li><li><span class=\"kw-alerte\">Spasmes musculaires généralisés</span> faisant suite au <span class=\"kw-clinique\">trismus</span></li><li><span class=\"kw-alerte\">Tétanos localisé</span> (un seul membre) pouvant <span class=\"kw-alerte\">précéder une généralisation</span> dans <span class=\"kw-chiffre\">25 à 50 %</span> des cas → PEC urgente même si localisé</li><li><span class=\"kw-def\">Pronostic</span> sévère : <span class=\"kw-alerte\">mortalité</span> ≈ <span class=\"kw-chiffre\">30 %</span></li></ul>","principes":"<p><strong>Trois temps :</strong> traiter la plaie, évaluer le statut vaccinal, décider <span class=\"kw-ttt\">vaccin</span> ± <span class=\"kw-ttt\">immunoglobulines</span>.</p><p><strong>Traitement de la plaie</strong></p><ul><li>Désinfecter la plaie</li><li><span class=\"kw-ttt\">Parage</span> : excision des tissus nécrotiques + ablation des corps étrangers</li><li><span class=\"kw-ci\">Pas de suture</span> tant que le parage n’est pas satisfaisant</li><li><span class=\"kw-ci\">Pas de pansement occlusif</span> (favorise l’anaérobiose et la germination des spores)</li><li><span class=\"kw-ttt\">Antibioprophylaxie</span> (Asclépia) : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> per os <span class=\"kw-chiffre\">5 jours</span> si plaie souillée</li></ul><p><strong>Évaluer le statut vaccinal</strong></p><ul><li><span class=\"kw-bio\">Carnet de vaccination</span> ou autre document médical</li><li><span class=\"kw-bio\">Tests immunologiques rapides</span> de détection des AC anti-tétaniques aux urgences (limitent <span class=\"kw-clinique\">les</span> prescriptions inutiles d’Ig)</li></ul><p><strong>Vaccin ± immunoglobulines (statut × plaie)</strong></p><ul><li><strong>Patient à jour</strong> : <span class=\"kw-ci\">ni vaccin ni séroprophylaxie</span>, préciser la date du prochain rappel</li><li><strong>Plaie mineure, propre</strong> + statut incomplet / inconnu : <span class=\"kw-ttt\">1 dose de vaccin</span> + programme de mise à jour</li><li><strong>Plaie majeure</strong> (étendue, pénétrante, corps étranger, traitée tardivement) + statut non à jour : <span class=\"kw-ttt\">vaccin</span> sur un bras + <span class=\"kw-ttt\">Ig tétaniques humaines</span> <span class=\"kw-chiffre\">250 UI</span> sur l’autre bras</li><li><strong>Tétanos déclaré</strong> : <span class=\"kw-ttt\">vaccination + sérothérapie</span> <span class=\"kw-chiffre\">immédiatement</span></li></ul><p><strong>Sérothérapie (immunoglobulines)</strong></p><ul><li><span class=\"kw-ttt\">Immunoglobulines humaines spécifiques anti-tétaniques</span> <span class=\"kw-chiffre\">250 UI</span> en IM</li><li>En même temps que la 1<sup>re</sup> dose vaccinale, mais sur un site différent (l’autre bras)</li><li><span class=\"kw-ci\">Jamais en IV</span>, <span class=\"kw-ci\">jamais mélangée au vaccin</span></li></ul><p><strong>Calendrier &amp; rattrapage vaccinal</strong></p><ul><li>Enfant : <span class=\"kw-chiffre\">2 mois</span>, <span class=\"kw-chiffre\">4 mois</span>, rappel <span class=\"kw-chiffre\">11 mois</span> ; rappels <span class=\"kw-chiffre\">6 ans</span> et <span class=\"kw-chiffre\">11-13 ans</span></li><li>Adulte : rappels <span class=\"kw-chiffre\">25 ans</span>, <span class=\"kw-chiffre\">45 ans</span>, <span class=\"kw-chiffre\">65 ans</span>, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">10 ans</span> dès <span class=\"kw-chiffre\">75 ans</span></li><li>Rattrapage adulte non / mal vacciné : <span class=\"kw-chiffre\">J0</span> – <span class=\"kw-chiffre\">+1 mois</span> – <span class=\"kw-chiffre\">+6 à 12 mois</span></li><li>Toujours un <span class=\"kw-ttt\">vaccin combiné</span> (<span class=\"kw-ttt\">dTP</span> / <span class=\"kw-ttt\">dTcaP</span>), <span class=\"kw-ci\">jamais de vaccin tétanique seul</span></li></ul>","suivi":"<p><strong>Maladie non immunisante :</strong> un tétanos déclaré ne protège pas d’une récidive → <span class=\"kw-ttt\">vacciner</span> le patient au décours.</p><p><strong><span class=\"kw-def\">Surveillance</span> :</strong> un <span class=\"kw-clinique\">tétanos localisé</span> peut se généraliser → surveillance rapprochée.</p><p><strong>Mise à jour :</strong> proposer systématiquement un <span class=\"kw-ttt\">programme de rattrapage</span> si le statut vaccinal est incomplet.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-160.pdf","label":"Collège Pilly — Tétanos (item 160, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient consultant pour une plaie — Évaluer le risque tétanigène","detail":"<h4>CAT — Plaie à risque tétanigène — Croiser statut vaccinal × type de plaie ; reconnaître le tétanos déclaré</h4>","branches":[{"to":"t-declare","label":"Trismus / spasmes après plaie souillée","color":"red"},{"to":"q-statut","label":"Plaie sans signe de tétanos","color":"green"}]},{"id":"t-declare","kind":"terminal","label":"Tétanos déclaré","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Trismus</span> (fébrile ou non) après une <span class=\"kw-etio\">plaie souillée</span></li><li><span class=\"kw-clinique\">Spasmes musculaires généralisés</span> secondaires</li><li>Maladie <span class=\"kw-clinique\">non douloureuse</span> et <span class=\"kw-clinique\">apyrétique</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Vaccination</span> + <span class=\"kw-ttt\">sérothérapie</span> <span class=\"kw-chiffre\">immédiatement</span>, sans attendre la confirmation <span class=\"kw-ttt\">biologique</span></li><li>Nettoyage et <span class=\"kw-ttt\">parage</span> soigneux de la plaie</li><li>± <span class=\"kw-ttt\">métronidazole</span> (<span class=\"kw-ttt\">antibiothérapie</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-alerte\">Risque de généralisation</span> ; <span class=\"kw-def\">pronostic</span> sévère (<span class=\"kw-alerte\">mortalité</span> ≈ <span class=\"kw-chiffre\">30 %</span>) ; maladie <span class=\"kw-alerte\">non immunisante</span> → poursuivre la <span class=\"kw-ttt\">vaccination</span></li></ul>"},{"id":"q-statut","kind":"decision","label":"Statut vaccinal antitétanique à jour ?","branches":[{"to":"t-ajour","label":"À jour","color":"green"},{"to":"q-plaie","label":"Incomplet / inconnu","color":"amber"}]},{"id":"t-ajour","kind":"terminal","label":"Patient à jour de ses vaccinations","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ci\">Ni vaccin ni séroprophylaxie</span> — préciser seulement la date du prochain rappel</li></ul><h4>Plaie</h4><ul><li>Soins locaux : désinfection, <span class=\"kw-ttt\">parage</span> si nécessaire</li></ul>"},{"id":"q-plaie","kind":"decision","label":"Type de plaie ?","branches":[{"to":"t-mineure","label":"Mineure, propre","color":"amber"},{"to":"t-majeure","label":"Majeure / souillée","color":"amber"}]},{"id":"t-mineure","kind":"terminal","label":"Plaie mineure propre","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">1 dose de vaccin</span> contenant la valence tétanique, immédiatement</li></ul><h4>Conduite</h4><ul><li>Proposer un <span class=\"kw-ttt\">programme de mise à jour</span> vaccinale (<span class=\"kw-chiffre\">J0</span> – <span class=\"kw-chiffre\">+1 mois</span> – <span class=\"kw-chiffre\">+6 à 12 mois</span>)</li></ul>"},{"id":"t-majeure","kind":"terminal","label":"Plaie majeure ou souillée — Étendue, pénétrante, corps étranger ou traitée tardivement","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Dose de vaccin</span> sur un bras</li><li><span class=\"kw-ttt\">Ig tétaniques humaines</span> <span class=\"kw-chiffre\">250 UI</span> en IM sur l’autre bras (couvre le délai d’apparition des anticorps)</li><li>Soins de plaie : <span class=\"kw-ttt\">parage</span>, <span class=\"kw-ci\">pas de suture</span> ni de <span class=\"kw-ci\">pansement occlusif</span></li></ul><h4>Conduite</h4><ul><li>Proposer un <span class=\"kw-ttt\">programme de mise à jour</span> vaccinale</li></ul>"}]},"cards":[{"i":"b7946a89d51b","n":160,"o":"160-1","u":"Physiopathologie","t":"Connaître les mécanismes du tétanos","q":"Quels sont les points essentiels concernant les mécanismes du tétanos ?","a":"<div class=\"notion-course\"><p>Le tétanos est une <strong><span>toxi-infection aiguë grave</span></strong> :\n      ce ne sont pas <span>les</span> bactéries elles-mêmes mais une <strong><span><span class=\"nc-pink nc-bold\">neurotoxine</span></span></strong>\n      qui est responsable des symptômes. La <strong><span>mortalité</span></strong> atteint\n      <span>≈ 30 %</span>.</p>\n\n      <table>\n        <thead><tr><th>Caractéristique</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Germe</strong></td>\n            <td><strong><span><span class=\"nc-purple_bg\">Clostridium tetani</span></span></strong> : <strong><span>bacille anaérobie strict</span></strong>,\n            <span>Gram positif</span>, <strong><span><span class=\"nc-brown nc-bold\">tellurique</span></span></strong>\n            (présent dans la terre, <span>les</span> objets souillés, les excréments) ; <span>forme sporulée résistante</span></td>\n          </tr>\n          <tr>\n            <td><strong>Toxine</strong></td>\n            <td>La <strong><span>tétanospasmine</span></strong>, produite par\n            <span>C. tetani</span> au niveau de la <span>plaie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Contagiosité</strong></td>\n            <td>Maladie <strong><span class=\"nc-green_bg\">non contagieuse</span></strong> — pas de transmission interhumaine</td>\n          </tr>\n          <tr>\n            <td><strong>Immunité</strong></td>\n            <td>Maladie <strong><span><span class=\"nc-red nc-bold\">non immunisante</span></span></strong> : un tétanos déclaré\n            ne protège pas — il faut vacciner le patient au décours</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Mécanisme de la maladie</strong>, étape par étape :</p>\n      <ul>\n        <li><strong><span>Porte d'entrée cutanée</span></strong> : la toxine est produite dans une\n        <span><span class=\"nc-red nc-bold\">plaie souillée</span></span>, souvent négligée</li>\n        <li><strong>Cheminement</strong> : la <span>tétanospasmine</span> gagne le\n        <span>système nerveux central</span> via <span>les</span> nerfs périphériques\n        (<strong><span>transport rétrograde axonal</span></strong>)</li>\n        <li><strong>Cible</strong> : elle bloque la libération du <strong><span>GABA</span></strong>\n        et de la <strong><span>glycine</span></strong> — <span>les</span> deux neurotransmetteurs inhibiteurs</li>\n        <li><strong>Conséquence</strong> : levée de l'inhibition →\n        <strong><span>hyperexcitabilité musculaire</span></strong> (contractures, spasmes)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Le tétanos est une maladie <span><span class=\"nc-red nc-bold\">non immunisante</span></span> :\n        avoir fait un tétanos ne protège pas d'un second épisode. La <span>vaccination</span> est donc\n        <strong>indispensable au décours</strong>, y compris après un tétanos déclaré.\n      </div></div>"},{"i":"0fee5f5c7f07","n":160,"o":"160-2","u":"Physiopathologie","t":"Connaître les modes de contamination du tétanos","q":"Quels sont les points essentiels concernant les modes de contamination du tétanos ?","a":"<div class=\"notion-course\"><p>La contamination se fait toujours par <strong>pénétration de <span>spores</span> de\n      <span>C. tetani</span></strong> dans l'organisme. Deux modes principaux :</p>\n      <ul>\n        <li><strong><span>Effraction cutanéomuqueuse</span></strong> : par une <strong><span><span class=\"nc-red nc-bold\">plaie</span></span></strong><span class=\"nc-red nc-bold\">\n        souillée</span> — <span>porte d'entrée</span> la plus fréquente</li>\n        <li><strong><span><span class=\"nc-orange nc-bold\">Post-partum</span> ou <span class=\"nc-orange nc-bold\">avortement septique</span></span></strong> : contamination lors de l'accouchement →\n        <strong><span>tétanos néonatal</span></strong> du nouveau-né (via le <span>cordon ombilical</span>),\n        dans <span>les</span> pays à <span class=\"nc-green_bg\">ressources limitées</span></li>\n      </ul>\n\n      <p>Le tétanos touche <span>les</span> <span class=\"nc-pink nc-bold\">sujets</span> <strong><span>non ou mal vaccinés</span></strong>. Les populations à risque\n      diffèrent selon le contexte :</p>\n      <table>\n        <thead><tr><th>Contexte</th><th>Population à risque</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Pays <span class=\"nc-green_bg\">développés</span></strong> (tétanos rare en Europe)</td>\n            <td>Surtout <strong><span><span class=\"nc-pink nc-bold\">sujets</span> <span class=\"nc-pink nc-bold\">âgés</span></span></strong>, avec\n            <strong><span>prédominance <span class=\"nc-pink nc-bold\">féminine</span></span></strong> (femmes historiquement moins bien vaccinées —\n            pas de service militaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Pays à <span class=\"nc-green_bg\">ressources limitées</span></strong></td>\n            <td><strong><span>Nouveau-nés</span></strong> de mère non vaccinée\n            (<span>tétanos néonatal</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le tétanos n'est <strong><span>pas contagieux</span></strong> : aucune transmission\n        interhumaine. La contamination est toujours environnementale (<span>origine <span class=\"nc-brown nc-bold\">tellurique</span></span>), via une\n        <span>porte d'entrée cutanéomuqueuse</span>.\n      </div></div>"},{"i":"e76a8749dbca","n":160,"o":"160-3","u":"Prise en charge","t":"Connaître les modalités de prévention du tétanos","q":"Quels sont les points essentiels concernant les modalités de prévention du tétanos ?","a":"<div class=\"notion-course\"><ul><li>Nettoyer et parer la plaie, retirer corps étrangers/tissus dévitalisés ; évaluer type de plaie et vaccination documentée. Les antibiotiques ne remplacent ni le vaccin ni les immunoglobulines ; pas d’amoxicilline–acide clavulanique systématique pour prévenir le tétanos.</li><li><span class=\"nc-blue nc-bold\">Vaccination</span> à jour : pas d’injection supplémentaire pour ce seul motif, rappeler la prochaine échéance. Plaie <span class=\"nc-green nc-bold\">mineure</span> <span class=\"nc-green nc-bold\">propre</span> et statut incomplet/inconnu : dose vaccinale puis rattrapage.</li><li>Plaie <span class=\"nc-red nc-bold\">majeure</span>/contaminée ou prise en charge tardive et <span class=\"nc-blue nc-bold\">vaccination</span> non à jour : vaccin plus immunoglobulines antitétaniques humaines, usuellement 250 UI IM, à un autre site ; suivre RCP et protocole.</li><li>Calendrier : 2, 4, 11 mois, rappels 6 ans, 11–13 ans, 25, 45, 65 ans puis tous les dix ans. Choisir valences et rattrapage selon calendrier actuel.</li><li>Un tétanos déclaré nécessite hospitalisation urgente, traitement spécifique et vaccination : la maladie n’immunise pas. La dose thérapeutique d’immunoglobulines ne se déduit pas automatiquement du schéma prophylactique de plaie.</li></ul></div>"},{"i":"afd163c22fe2","n":160,"o":"160-4","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques devant faire suspecter un tétanos","q":"Quels sont les points essentiels concernant les principaux signes cliniques devant faire suspecter un tétanos ?","a":"<div class=\"notion-course\"><ul><li>Évoquer le tétanos devant <span class=\"nc-red nc-bold\">trismus</span>, dysphagie, raideur et spasmes chez une personne insuffisamment vaccinée, même si la porte d’entrée est minime, cicatrisée ou inconnue.</li><li>Le trismus initial est classiquement peu <span class=\"nc-red nc-bold\">douloureux</span> et sans fièvre ; les contractures/<span class=\"nc-yellow_bg\">spasmes généralisés</span> peuvent être très <span class=\"nc-red nc-bold\">douloureux</span>, déclenchés par bruit ou contact. Ne pas qualifier toute la maladie de « non douloureuse ».</li><li>Conscience souvent conservée ; risque de spasme laryngé, insuffisance respiratoire et dysautonomie. Formes localisées ou céphaliques possibles, avec risque de généralisation.</li><li>Diagnostic clinique : prise en charge urgente sans attendre culture ou recherche de toxine. Une fièvre ou une douleur imposent aussi la recherche d’une cause locale/complication, sans exclure à elles seules le tétanos.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d941815e8a4dff027cb4c42c?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
